def page(locale, d):
    base = f"https://www.bigfame.co/{locale}/jewelry-display-accessories"
    alt = ''.join(f'<link rel="alternate" hreflang="{h}" href="https://www.bigfame.co/{l}/jewelry-display-accessories">' for h, l in (("zh-TW", "tw"), ("en", "en"), ("ja", "jp")))
    collection = json.dumps({"@context": "https://schema.org", "@type": "CollectionPage", "name": d["title"], "description": d["description"], "url": base}, ensure_ascii=False)
    crumb = json.dumps({"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "Big Fame", "item": f"https://www.bigfame.co/{locale}/"}, {"@type": "ListItem", "position": 2, "name": d["nav"][1], "item": f"https://www.bigfame.co/{locale}/products"}, {"@type": "ListItem", "position": 3, "name": d["title"], "item": base}]}, ensure_ascii=False)
    faq = json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in d["faq"]]}, ensure_ascii=False)
    cards = ''.join(f'<article class="location-card reveal"><h3>{html.escape(h)}</h3><p>{html.escape(b)}</p></article>' for h, b in d["records"])
    faqs = ''.join(f'<article class="location-card reveal"><h3>{html.escape(q)}</h3><p>{html.escape(a)}</p></article>' for q, a in d["faq"])
    contact = "contact?role=designer&category=custom_metal_components&requested_files=dimension_drawing"
    img_alt = {"tw": "珠寶展示空間示意圖，非本案正式照片", "en": "Illustrative jewelry display space, not a formal project photograph", "jp": "ジュエリー展示空間のイメージ。本件の正式写真ではありません"}[locale]
    boundary = {"tw": "本頁為匿名設計／規格紀錄；示意圖不是本案正式照片，正式圖面、材料、數量、交期與交付條件需逐案確認。", "en": "This is an anonymous design/specification record. The image is illustrative, not a formal project photograph; confirm drawings, materials, quantity, schedule and delivery conditions case by case.", "jp": "匿名の設計／仕様記録です。画像はイメージで正式写真ではありません。図面、材料、数量、納期、納品条件は案件ごとに確認します。"}[locale]
    return f'''<!DOCTYPE html><html lang="{d["lang"]}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="{html.escape(d["description"], quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(d["title"], quote=True)} | Big Fame"><meta property="og:description" content="{html.escape(d["description"], quote=True)}"><meta property="og:url" content="{base}"><meta property="og:site_name" content="Big Fame IND. CORP."><title>{html.escape(d["title"])} | Big Fame</title><link rel="canonical" href="{base}">{alt}<link rel="stylesheet" href="../css/style.css"><script type="application/ld+json">{collection}</script><script type="application/ld+json">{crumb}</script><script type="application/ld+json">{faq}</script></head><body><header class="header"><div class="container header-inner"><a href="./" class="logo">BIG FAME</a><nav class="nav-menu"><a href="./" class="nav-link">{d["nav"][0]}</a><a href="products" class="nav-link active">{d["nav"][1]}</a><a href="applications" class="nav-link">{d["nav"][2]}</a><a href="{contact}" class="nav-link nav-cta">{d["nav"][3]}</a></nav></div></header><main><section class="hero"><div class="container hero-content reveal"><p class="hero-kicker">ANONYMOUS DESIGN / SPECIFICATION RECORD</p><h1>{html.escape(d["title"])}</h1><p class="hero-description">{html.escape(d["description"])}</p><a class="btn btn-primary" href="{contact}">{html.escape(d["cta"])}</a><p class="section-note reveal">{html.escape(boundary)}</p><div class="product-visual reveal"><img src="../images/case_e_jewelry.jpg" alt="{html.escape(img_alt, quote=True)}" loading="lazy"></div></div></section><section class="section section-light"><div class="container grid-2"><div class="location-card reveal"><span class="section-subtitle">DESIGN NEED</span><h2>{html.escape(d["need_title"])}</h2><p>{html.escape(d["need"])}</p></div><div class="location-card reveal"><span class="section-subtitle">EVIDENCE BOUNDARY</span><p>{html.escape(boundary)}</p><p><a href="custom-metal-parts">{html.escape({"tw":"客製金屬零件", "en":"Custom metal parts", "jp":"カスタム金属部品"}[locale])}</a> · <a href="technical-resources">{html.escape({"tw":"技術與 CAD 資源", "en":"Technical resources", "jp":"技術・CAD資料"}[locale])}</a></p></div></div></section><section class="section section-light"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">SOURCE RECORD</span><h2 class="section-title">{html.escape({"tw":"圖面可核對的條件", "en":"Conditions traceable to the drawings", "jp":"図面から確認できる条件"}[locale])}</h2></div><div class="grid-3">{cards}</div></div></section><section class="section section-light" data-bf-faq="1"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">FAQ</span><h2 class="section-title">FAQ</h2></div><div class="grid-2">{faqs}</div></div></section><section class="section section-dark"><div class="container"><div class="cta-block reveal"><h2>{html.escape(d["cta"])}</h2><p><a href="custom-metal-parts">{html.escape({"tw":"客製金屬零件", "en":"Custom metal parts", "jp":"カスタム金属部品"}[locale])}</a> · <a href="design-support">{html.escape({"tw":"設計支援", "en":"Design support", "jp":"設計支援"}[locale])}</a></p><a class="btn btn-primary" href="{contact}">{html.escape(d["nav"][3])}</a></div></div></section></main><footer class="footer"><div class="container footer-bottom"><p>© Big Fame IND. CORP.</p><a href="products">{d["nav"][1]}</a></div></footer><script src="../js/main.js"></script></body></html>'''

for locale, data in DATA.items():
    flat = ROOT / locale / "jewelry-display-accessories.html"
    flat.write_text(page(locale, data), encoding="utf-8")
    clean = ROOT / locale / "jewelry-display-accessories" / "index.html"
    clean.parent.mkdir(exist_ok=True)
    clean.write_text(page(locale, data).replace('../css/style.css', '../../css/style.css').replace('../images/case_e_jewelry.jpg', '../../images/case_e_jewelry.jpg').replace('../js/main.js', '../../js/main.js').replace('href="./"', 'href="../"').replace('href="products"', 'href="../products"').replace('href="applications"', 'href="../applications"').replace('href="custom-metal-parts"', 'href="../custom-metal-parts"').replace('href="technical-resources"', 'href="../technical-resources"').replace('href="design-support"', 'href="../design-support"').replace('href="contact?', 'href="../contact?'), encoding="utf-8")
print("Generated localized anonymous jewelry-display specification records.")
